insert into profiles (user_id, slug, program, pitch, tags, open_to_team, open_to_friends, template, site_url, links, content, published) values
  ('a4f49356-334a-4fbb-845b-a4a9293b062c', 'patricia-piccinini', 'VCA 绘画 · 1991 届 · 精选校友', '当代艺术家，做雕塑、装置和影像。1991 年 VCA 绘画系毕业，2003 年代表澳大利亚参加威尼斯双年展。', '{"当代艺术","雕塑","装置"}', false, false, null, 'https://www.patriciapiccinini.net/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Patricia_Piccinini"}]', '{"about":"Patricia Piccinini，1965 年生，作品围绕生物伦理和后人类议题，以超写实的人兽混合体雕塑知名。1991 年在 VCA 取得绘画学士，2016 年获墨尔本大学 VCA 荣誉博士。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"patriciapiccinini.net","url":"https://www.patriciapiccinini.net/","image":"https://unimelbwall.com/skillwall/uploads/85b7e209-086b-464c-98dc-e78e248a4f88.jpg"}]}', true),
  ('a9fe2f63-0edb-44d4-a061-b32a10ce42da', 'ricky-swallow', 'VCA 素描 · 1997 届 · 精选校友', '雕塑家，现居洛杉矶。1997 年 VCA 素描专业毕业，两年后拿下 Contempora 5 奖，2005 年代表澳大利亚参加威尼斯双年展。', '{"雕塑","当代艺术"}', false, false, null, 'https://www.rickyswallow.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ricky_Swallow"}]', '{"about":"Ricky Swallow，1974 年生于维多利亚州 San Remo，常以日常物件和身体为题做精细的雕塑与装置。1993–97 年在 VCA 读美术学士（素描）。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"rickyswallow.com","url":"https://www.rickyswallow.com/","image":"https://unimelbwall.com/skillwall/uploads/bf0e2ca7-9444-4061-a1fc-73825fe21afc.jpg"}]}', true),
  ('1cae8c81-3d6a-435b-8780-9cb8514ca3dd', 'sally-smart', 'VCA 美术硕士 · 1991 届 · 精选校友', '当代艺术家，以大型拼贴装置知名。在 VCA 读了绘画研究生文凭（1988）和美术硕士（1991）。', '{"装置","拼贴","当代艺术"}', false, false, null, 'https://www.sallysmart.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sally_Smart"}]', '{"about":"Sally Smart，1960 年生，用毛毡剪影、布面、丝网印和影像做大型装置，讨论性别与身份。此前在阿德莱德学过平面设计，2017 年任墨尔本大学校长学者。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"sallysmart.com","url":"https://www.sallysmart.com/","image":"https://unimelbwall.com/skillwall/uploads/01d80c55-b8b4-4325-b98a-871d23205adc.jpg"}]}', true),
  ('7f602b60-d69d-4bc9-b197-3f48038ca8d4', 'yvette-coppersmith', 'VCA 绘画 · 2001 届 · 精选校友', '画家，专攻肖像和静物。2001 年 VCA 绘画专业毕业，2018 年凭自画像获 Archibald Prize。', '{"绘画","肖像"}', false, false, null, 'https://www.yvettecoppersmith.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Yvette_Coppersmith"}]', '{"about":"Yvette Coppersmith，1980 年生。2001 年在 VCA 读完美术学士（绘画），2003 年是 Metro 5 Art Prize 的首届得主，2018 年以一幅 George Lambert 风格的自画像赢得 Archibald Prize。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"yvettecoppersmith.com","url":"https://www.yvettecoppersmith.com/","image":"https://unimelbwall.com/skillwall/uploads/f9e647fa-30e1-4a32-9c01-b78e47a38068.jpg"}]}', true),
  ('e2f33509-54ff-499c-9dce-c0f8782a72e8', 'ash-keating', 'VCA 绘画（荣誉） · 2006 届 · 精选校友', '当代视觉艺术家，用灌了颜料的灭火器喷出的大型户外壁画遍布墨尔本。2006 年 VCA 绘画荣誉学士。', '{"绘画","壁画","当代艺术"}', false, false, null, 'https://www.ashkeating.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ash_Keating"}]', '{"about":"Ash Keating，1980 年生，创作跨绘画、行为、雕塑和影像。2004 年在莫纳什读完绘画学士，2006 年在 VCA 取得一等荣誉学士。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"ashkeating.com","url":"https://www.ashkeating.com/","image":"https://unimelbwall.com/skillwall/uploads/736f3c2e-b3ae-41c8-863d-6ad19728c233.jpg"}]}', true),
  ('8d87d335-6ab2-4442-a476-8756f71fb16e', 'jacqui-stockdale', 'VCA 绘画 · 1990 届 · 精选校友', '当代艺术家，做戏剧化的肖像，跨绘画、摄影、拼贴和表演。1990 年 VCA 绘画学士。', '{"绘画","摄影","肖像"}', false, false, null, 'https://www.jacquistockdale.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacqui_Stockdale"}]', '{"about":"Jacqui Stockdale，1968 年生，作品探讨面具、民俗、仪式与身份。1990 年 VCA 绘画学士，1993 年在塔斯马尼亚大学读完影像艺术研究生文凭。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"jacquistockdale.com","url":"https://www.jacquistockdale.com/","image":"https://unimelbwall.com/skillwall/uploads/64cf27ee-cde0-4a1e-80b9-04e831bf7c22.jpg"}]}', true),
  ('a571c0a3-bf47-4db5-8d0b-f8739f61c8ca', 'jan-nelson', 'VCA · 1983 届 · 精选校友', '艺术家，做雕塑、摄影和绘画，以超写实的青少年肖像知名。1983 年毕业于 VCA。', '{"绘画","摄影","雕塑"}', false, false, null, 'https://www.jan-nelson.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jan_Nelson"}]', '{"about":"Jan Nelson，1955 年生于墨尔本，作品被澳大利亚国家美术馆、维多利亚国立美术馆等收藏。1983 年毕业于 VCA。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"jan-nelson.com","url":"https://www.jan-nelson.com/","image":"https://unimelbwall.com/skillwall/uploads/d4c9e156-87bd-455c-83b7-fba34fdb5197.jpg"}]}', true),
  ('13ea3bd2-856a-451e-8d8a-0882946ea454', 'christopher-beaumont', 'VCA 绘画与雕塑 · 1987 届 · 精选校友', '静物画家。1983 年拿到墨尔本大学的学位，1987 年又在 VCA 读完绘画与雕塑学士。', '{"绘画","静物"}', false, false, null, 'https://www.chrisbeaumont.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christopher_Beaumont"}]', '{"about":"Christopher Beaumont，1961 年生，作品被多家机构和企业收藏。1983 年墨尔本大学毕业，1987 年 VCA 绘画与雕塑学士。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"chrisbeaumont.com","url":"https://www.chrisbeaumont.com/","image":"https://unimelbwall.com/skillwall/uploads/b11c7bf2-89d9-4c1f-a4c1-57a998842a5d.jpg"}]}', true),
  ('9bfdaa86-e158-4584-9d30-e1800e22ce61', 'adam-elliot', 'VCA 影视（动画） · 1996 届 · 精选校友', '黏土动画导演，把自己的片子叫 Clayography（黏土传记）。1996 年在 VCA 读完影视研究生文凭，主修动画。', '{"动画","黏土动画","电影"}', false, false, null, 'https://www.adamelliot.au/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Adam_Elliot"}]', '{"about":"Adam Elliot，墨尔本的独立动画导演，作品多取材于家人和朋友，悲喜交加。第一部短片《Uncle》就是 1996 年在 VCA 做的，后来有《Harvie Krumpet》《Mary and Max》等。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"adamelliot.au","url":"https://www.adamelliot.au/","image":"https://unimelbwall.com/skillwall/uploads/4dbc8961-69cb-49d7-9234-cfb4ce036e35.jpg"}]}', true),
  ('75ec535f-dbe6-41b0-9760-aedc9e8ccfbd', 'emma-freeman', 'VCA 影视 · 毕业年份未公开 · 精选校友', '影视导演。VCA 毕业，2002 年凭短片《Lamb》成为第一位赢得 Tropfest 的女性，执导过 Glitch 和 The Newsreader。', '{"导演","电视剧","电影"}', false, false, null, 'https://www.emmafreemanfilms.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Emma_Freeman"}]', '{"about":"Emma Freeman，澳大利亚电视剧和电视电影导演，毕业于 VCA。作品包括 Glitch、The Newsreader（2021–2025）和 The Family Next Door（2025）。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"emmafreemanfilms.com","url":"https://www.emmafreemanfilms.com/","image":"https://unimelbwall.com/skillwall/uploads/f3a0232f-bfd8-4685-9558-9791f361221f.jpg"}]}', true),
  ('fca011f5-8795-4bae-8e07-82e82ff50251', 'judy-horacek', '墨大 文学士 · 1991 届 · 精选校友', '漫画家、绘本作者。1991 年墨尔本大学文学士，主修美术和英语；和 Mem Fox 合作了绘本《Where is the Green Sheep?》。', '{"漫画","插画","绘本"}', false, false, null, 'https://horacek.com.au/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Judy_Horacek"}]', '{"about":"Judy Horacek，1961 年生，长期为 The Age、The Canberra Times 等报纸画漫画，出过十本漫画集。1991 年墨尔本大学文学士。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"horacek.com.au","url":"https://horacek.com.au/","image":"https://unimelbwall.com/skillwall/uploads/2f8e94cc-ef28-48ec-954e-53da94c0144e.jpg"}]}', true),
  ('fc798492-0349-4ed6-a01b-c1cdabe56650', 'martin-grant', 'VCA 雕塑 · 1980 年代末就读 · 精选校友', '旅居巴黎的时装设计师。21 岁进 VCA 学雕塑，读了两年，1990 年离开澳洲，经伦敦到巴黎重开自己的品牌；NGV 在 2005 和 2025 年为他办过展。', '{"时装设计","设计"}', false, false, null, 'http://www.martingrantparis.com/en', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Martin_Grant"}]', '{"about":"Martin Grant，1966 年生，为 Cate Blanchett、Tilda Swinton 等人做过衣服。年轻时已在时装界成名，仍去 VCA 学了两年雕塑，没读完便离开澳洲，先到伦敦，后定居巴黎。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"martingrantparis.com","url":"http://www.martingrantparis.com/en","image":"https://unimelbwall.com/skillwall/uploads/ffe82e36-034d-4169-b86b-92f877db13c1.jpg"}]}', true),
  ('5304159b-a230-4cd9-a76c-42fdcc7201ca', 'simone-leamon', 'VCA 美术 · 1992 届 · 精选校友', '设计师、策展人。1992 年 VCA 美术学士；现任澳大利亚设计协会 CEO，2015–25 年是 NGV 首任当代设计与建筑策展人。', '{"设计","策展"}', false, false, null, 'https://www.simoneleamon.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Simone_LeAmon"}]', '{"about":"Simone LeAmon，设计师、艺术家、策展人和教育者，RMIT 兼职教授。1992 年毕业于 VCA。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"simoneleamon.com","url":"https://www.simoneleamon.com/","image":"https://unimelbwall.com/skillwall/uploads/7e946799-d4a8-4552-ae86-edcf7815026b.jpg"}]}', true),
  ('6d1845cc-7cc4-45fa-9761-573bd645f9cd', 'cameron-adams', '墨大 法学 + 理学 · 2002 届 · 精选校友', 'Canva 联合创始人、首席产品官。2002 年墨尔本大学法学加理学毕业，毕业后做平面设计师建网站，后来去 Google 做 Wave 的设计。', '{"平面设计","产品设计","创业"}', false, false, null, 'https://themaninblue.com/', '[{"label":"墨大校友杂志","url":"https://mag.alumni.unimelb.edu.au/simply-startups/"}]', '{"about":"Cameron Adams，个人网站叫 The Man in Blue。读的是法律和计算机，毕业后开了自己的设计工作室，2007 年加入 Google，之后和 Melanie Perkins、Cliff Obrecht 一起做了 Canva。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"themaninblue.com","url":"https://themaninblue.com/","image":"https://unimelbwall.com/skillwall/uploads/07ed9309-ed07-4811-87ce-0808e51bff6b.jpg"}]}', true),
  ('d509f057-ce0b-4d9e-a003-a170f4d33f97', 'sean-godsell', '墨大 建筑 · 1984 届 · 精选校友', '建筑师。1984 年墨尔本大学毕业，主持 Sean Godsell Architects。', '{"建筑","设计"}', false, false, null, 'https://www.seangodsell.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sean_Godsell"}]', '{"about":"Sean Godsell，1960 年生，澳大利亚建筑师。1984 年毕业于墨尔本大学。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"seangodsell.com","url":"https://www.seangodsell.com/","image":"https://unimelbwall.com/skillwall/uploads/c78b9b2d-363d-4292-b81f-0747afda18bd.jpg"}]}', true),
  ('a40e10c9-d006-4b73-b495-42447af34c9b', 'michael-meszaros', '墨大 建筑 · 1968 届 · 精选校友', '雕塑家、纪念章艺术家。1968 年墨尔本大学建筑系毕业，后来转做雕塑。', '{"雕塑","纪念章"}', false, false, null, 'https://meszarossculptor.com/site', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Michael_Meszaros"}]', '{"about":"Michael Meszaros OAM，1945 年生于墨尔本。1960 年代在墨尔本大学学建筑，1968 年毕业。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"meszarossculptor.com","url":"https://meszarossculptor.com/site","image":"https://unimelbwall.com/skillwall/uploads/b37e3e39-b43b-4b3e-9c96-2ce6f47db1b2.jpg"}]}', true),
  ('342aed1a-7426-4dab-b081-d31cb0fd0378', 'hugh-davies', 'VCA · 1997–99 就读 · 精选校友', '媒体艺术创作者和研究者。1997–99 年在 VCA 受训，创办了协作艺术项目 Analogue Art Map。', '{"媒体艺术","研究"}', false, false, null, 'https://www.hughdavies.au/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hugh_Davies_(artist)"}]', '{"about":"Hugh Davies，1971 年生。在 VCA 和哥本哈根技术学院受训，在澳大利亚广播公司工作期间获 2008 年 ATOM 奖。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"hughdavies.au","url":"https://www.hughdavies.au/","image":"https://unimelbwall.com/skillwall/uploads/1c1e1930-9265-4c99-a509-1586fff4ccf4.jpg"}]}', true),
  ('b58fd4f5-f2fd-481f-bdc4-27bdccaae5c3', 'john-dahlsen', 'VCA · 1977–79 就读 · 精选校友', '环境艺术家，用海滩上捡来的塑料垃圾做作品。1977–79 年在 VCA 学艺术。', '{"环境艺术","装置"}', false, false, null, 'https://johndahlsen.com/', '[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Dahlsen"}]', '{"about":"John Dahlsen，澳大利亚当代环境艺术家，材料主要是澳洲海滩上的海洋塑料垃圾。1977–79 年就读 VCA，1989 年在墨尔本高等教育学院进修。\n\n这张名片是技能墙整理的精选示例：资料来自维基百科等公开页面，链接是其官方个人网站，封面是该网站首页的截图（2026-09-29）。本人并未入驻技能墙；如需更正或移除，请通过站内「意见反馈」联系我们。","works":[{"title":"官方个人网站","description":"johndahlsen.com","url":"https://johndahlsen.com/","image":"https://unimelbwall.com/skillwall/uploads/f68f2114-dc03-4906-bff8-853b57d8b1f7.jpg"}]}', true);
